        # SEGMENT 1: Intro & Problem statement (23.1s)
        # -------------------------------------------------------------
        print("\n--- Segment 1: Problem & Solution Intro ---")
        t0 = time.time()
        seg1_target = SEGMENT_TIMINGS[0]["dur"] + SEGMENT_TIMINGS[0]["pause"]
        
        # Smoothly move mouse across hero title
        await page.mouse.move(960, 220)
        await asyncio.sleep(2.5)
        await page.mouse.move(960, 360)
        await asyncio.sleep(3.0)
        
        # Hover the 1-Click Judge Demo hero banner
        demo_btn = page.locator("button:has-text('Judge live demo'), button[title*='VIT-AP']").first
        await demo_btn.hover()
        await asyncio.sleep(3.5)
        
        # Hover features grid cards below
        await page.mouse.move(500, 640)
        await asyncio.sleep(3.0)
        await page.mouse.move(960, 640)
        await asyncio.sleep(3.0)
        await page.mouse.move(1420, 640)
        await asyncio.sleep(3.0)
        
        # Hover back to hero button
        await demo_btn.hover()
        rem1 = seg1_target - (time.time() - t0)
        if rem1 > 0:
            await asyncio.sleep(rem1)
        print(f"  Segment 1 finished in {time.time() - t0:.2f}s (target: {seg1_target:.2f}s)")
        
        # -------------------------------------------------------------
        # SEGMENT 2: 1-Click Judge Demo & Curriculum Ingestion (29.77s)
        # -------------------------------------------------------------
