def merge_video_and_audio(raw_video_path, full_audio_path, output_mp4_path):
    print("\n=== Merging Full HD Video & Studio Narration Track with FFmpeg ===")
    
    cmd = [
        "ffmpeg", "-y",
        "-i", raw_video_path,
        "-i", full_audio_path,
        "-c:v", "libx264",
        "-preset", "medium",
        "-crf", "18",
        "-pix_fmt", "yuv420p",
        "-c:a", "aac",
        "-b:a", "192k",
        "-shortest",
        output_mp4_path
    ]
    
    print("Running command:", " ".join(cmd))
    subprocess.run(cmd, check=True)
    
    # Probe final output file
    res = subprocess.run([
        "ffprobe", "-v", "error", "-show_entries", "format=duration,size",
        "-of", "default=noprint_wrappers=1", output_mp4_path
    ], capture_output=True, text=True, check=True)
    
    print("\n" + "="*60)
    print("SUCCESS: CHAMPIONSHIP DEMO VIDEO CREATED SUCCESSFULLY!")
    print(f"File Path: {os.path.abspath(output_mp4_path)}")
    print(res.stdout.strip())
    print("="*60)

async def main():
    audio_path = os.path.join(OUTPUT_DIR, "full_narration.mp3")
    if not os.path.exists(audio_path):
        print("Audio track not found! Generating audio first...")
        import build_audio
        await build_audio.build_audio()
        
    raw_video = await record_walkthrough()
    output_mp4 = os.path.join(OUTPUT_DIR, "syncup_ai_demo.mp4")
    merge_video_and_audio(raw_video, audio_path, output_mp4)

if __name__ == "__main__":
    asyncio.run(main())
